// Wonders: great works of building and engineering, shown from the year they were finished (from; c: approximate)
// until they were destroyed or lost (to; none if they still stand). at: [lon, lat]. wiki: English Wikipedia article
// (build.py fetches its lead text and image). The power that built one is whichever civilisation is drawn there.
const WONDERS = [
  { id: 'stonehenge', name: 'Stonehenge', at: [-1.826, 51.179], from: -2500, c: true, wiki: 'Stonehenge', note: 'A ring of standing stones on Salisbury Plain, its great sarsens raised around 2500 BC and aligned on the midsummer sunrise and midwinter sunset. Some of its bluestones were dragged from Wales, 225 km away.' },
  { id: 'pyramids', name: 'Great Pyramid of Giza', at: [31.134, 29.979], from: -2560, c: true, wiki: 'Great Pyramid of Giza', note: 'The tomb of the pharaoh Khufu, built of some 2.3 million stone blocks. At 146 m it was the tallest building in the world for almost 4,000 years, and it is the only one of the ancient Seven Wonders still standing.' },
  { id: 'ziggurat', name: 'Great Ziggurat of Ur', at: [46.103, 30.963], from: -2100, c: true, wiki: 'Great Ziggurat of Ur', note: 'A stepped temple platform of mud brick built by King Ur-Nammu for the moon god Nanna, the best preserved of the ziggurats of Mesopotamia.' },
  { id: 'abusimbel', name: 'Abu Simbel', at: [31.626, 22.336], from: -1264, c: true, wiki: 'Abu Simbel', note: 'Two temples cut into a Nubian cliff by Ramesses II, fronted by four 20 m statues of the king, facing south to awe Egypt’s neighbours. In the 1960s they were cut up and moved above the rising waters of Lake Nasser.' },
  { id: 'persepolis', name: 'Persepolis', at: [52.891, 29.935], from: -515, to: -330, c: true, wiki: 'Persepolis', note: 'The ceremonial capital of the Persian kings, where reliefs show envoys of 23 peoples bringing tribute. Alexander burned it in 330 BC; its columns still stand.' },
  { id: 'artemis', name: 'Temple of Artemis', at: [27.364, 37.950], from: -550, to: 401, c: true, wiki: 'Temple of Artemis', note: 'The great marble temple of Ephesus, paid for in part by King Croesus of Lydia, burned in 356 BC and rebuilt even larger. It was finally pulled down in the 5th century; one column has been re-erected.' },
  { id: 'ishtar', name: 'Ishtar Gate', at: [44.421, 32.543], from: -575, wiki: 'Ishtar Gate', note: 'Nebuchadnezzar II’s gate to Babylon, of blue glazed brick with dragons and bulls, on the processional way. Its remains were excavated and rebuilt in a Berlin museum.' },
  { id: 'parthenon', name: 'Parthenon', at: [23.726, 37.971], from: -432, wiki: 'Parthenon', note: 'Athena’s temple on the Acropolis of Athens, paid for with the tribute of Athens’ allies at the height of its democracy. A church and then a mosque, it was blown up in 1687 when an Ottoman powder store inside was hit.' },
  { id: 'zeus', name: 'Statue of Zeus at Olympia', at: [21.630, 37.638], from: -435, to: 425, c: true, wiki: 'Statue of Zeus at Olympia', note: 'Phidias’ seated Zeus of gold and ivory, about 12 m high, in the temple at the site of the Olympic Games. It was lost in the 5th century AD.' },
  { id: 'mausoleum', name: 'Mausoleum at Halicarnassus', at: [27.424, 37.038], from: -350, to: 1494, c: true, wiki: 'Mausoleum at Halicarnassus', note: 'The tomb of Mausolus, a Persian satrap, so splendid that its name came to mean any grand tomb. Earthquakes toppled it and the Knights of St John reused its stones for their castle.' },
  { id: 'lighthouse', name: 'Lighthouse of Alexandria', at: [29.885, 31.214], from: -280, to: 1323, c: true, wiki: 'Lighthouse of Alexandria', note: 'A tower over 100 m high on the island of Pharos guiding ships into Alexandria, among the tallest buildings in the world for centuries. Earthquakes brought it down by 1323.' },
  { id: 'library', name: 'Library of Alexandria', at: [29.909, 31.207], from: -285, to: 272, c: true, wiki: 'Library of Alexandria', note: 'The Ptolemies tried to gather every book in the world here, copying those found on ships in the harbour. It declined over centuries and was probably gone by the time Aurelian’s troops wrecked the palace quarter in 272.' },
  { id: 'colossus', name: 'Colossus of Rhodes', at: [28.227, 36.451], from: -280, to: -226, wiki: 'Colossus of Rhodes', note: 'A bronze statue of the sun god Helios about 33 m high, put up by Rhodes to celebrate surviving a siege. An earthquake felled it 54 years later, and the ruins lay where they fell for 800 years.' },
  { id: 'sanchi', name: 'Great Stupa at Sanchi', at: [77.739, 23.479], from: -250, c: true, wiki: 'Sanchi', note: 'A Buddhist relic mound begun by Ashoka, with carved stone gateways added around 50 BC that tell the life of the Buddha.' },
  { id: 'greatwall', name: 'Great Wall of China', at: [116.016, 40.359], from: -214, wiki: 'Great Wall of China', note: 'The First Emperor joined older walls into a defence against the steppe nomads; later dynasties rebuilt it many times. Most of what stands today is the brick and stone wall of the Ming.' },
  { id: 'terracotta', name: 'Terracotta Army', at: [109.273, 34.385], from: -210, wiki: 'Terracotta Army', note: 'Some 8,000 life-size clay soldiers with horses and chariots buried to guard the tomb of the First Emperor, each face apparently different. Farmers digging a well found them in 1974.' },
  { id: 'colosseum', name: 'Colosseum', at: [12.492, 41.890], from: 80, wiki: 'Colosseum', note: 'Rome’s great amphitheatre, seating perhaps 50,000 for gladiator fights and wild beast hunts, built with the spoils of the Jewish War.' },
  { id: 'pantheon', name: 'Pantheon', at: [12.477, 41.899], from: 126, c: true, wiki: 'Pantheon, Rome', note: 'Hadrian’s temple to all the gods. Its unreinforced concrete dome, 43 m across with an open eye at the top, is still the largest of its kind.' },
  { id: 'teotihuacan', name: 'Pyramid of the Sun', at: [-98.844, 19.692], from: 200, c: true, wiki: 'Pyramid of the Sun', note: 'The largest building of Teotihuacan, then one of the biggest cities in the world. The Aztecs, finding it in ruins a thousand years later, named it.' },
  { id: 'nalanda', name: 'Nalanda', at: [85.444, 25.136], from: 427, to: 1200, c: true, wiki: 'Nalanda mahavihara', note: 'A Buddhist monastery and university with thousands of monks and a great library, where Xuanzang studied. It was sacked around 1200.' },
  { id: 'hagiasophia', name: 'Hagia Sophia', at: [28.980, 41.009], from: 537, wiki: 'Hagia Sophia', note: 'Justinian’s cathedral of Constantinople, whose dome seemed to its builders to hang from heaven. For almost a thousand years it was the largest church in the world, then a mosque from 1453.' },
  { id: 'grandcanal', name: 'Grand Canal', at: [119.43, 32.39], from: 609, wiki: 'Grand Canal (China)', note: 'The Sui joined older canals into a waterway of some 1,800 km carrying the rice of the south to the capitals of the north. It is the longest canal in the world.' },
  { id: 'domerock', name: 'Dome of the Rock', at: [35.235, 31.778], from: 691, wiki: 'Dome of the Rock', note: 'An Umayyad shrine over the rock on Jerusalem’s Temple Mount, the oldest surviving major Islamic building, with its golden dome and mosaics.' },
  { id: 'cordoba', name: 'Great Mosque of Córdoba', at: [-4.779, 37.879], from: 786, wiki: 'Mosque–Cathedral of Córdoba', note: 'The mosque of the Umayyad emirs of al-Andalus, a forest of more than 800 columns under red and white arches. A cathedral was built into its middle after 1523.' },
  { id: 'borobudur', name: 'Borobudur', at: [110.204, -7.608], from: 825, c: true, wiki: 'Borobudur', note: 'A Buddhist monument in Java built as a mountain of nine terraces, with over 2,600 carved panels that pilgrims pass as they climb. It was abandoned and overgrown, and cleared from 1814.' },
  { id: 'wisdom', name: 'House of Wisdom', at: [44.36, 33.31], from: 830, to: 1258, c: true, wiki: 'House of Wisdom', note: 'The Abbasid library in Baghdad where Greek, Persian and Indian works were translated into Arabic and scholars such as al-Khwarizmi worked. It was destroyed when the Mongols sacked Baghdad.' },
  { id: 'chichen', name: 'El Castillo, Chichen Itza', at: [-88.569, 20.683], from: 1000, c: true, wiki: 'El Castillo, Chichen Itza', note: 'A stepped pyramid with 365 steps in all; at the equinoxes the evening sun casts a serpent of light down its stairway.' },
  { id: 'angkor', name: 'Angkor Wat', at: [103.867, 13.412], from: 1150, c: true, wiki: 'Angkor Wat', note: 'Built by Suryavarman II as a Hindu temple to Vishnu and later a Buddhist one, it is the largest religious monument in the world, a model of the universe in sandstone.' },
  { id: 'lalibela', name: 'Churches of Lalibela', at: [39.041, 12.032], from: 1200, c: true, wiki: 'Rock-Hewn Churches, Lalibela', note: 'Eleven churches carved down into the solid rock of the Ethiopian highlands, meant as a new Jerusalem for pilgrims who could not reach the old one.' },
  { id: 'moai', name: 'Moai of Rapa Nui', at: [-109.35, -27.12], from: 1250, c: true, wiki: 'Moai', note: 'Nearly 1,000 stone figures of ancestors carved by the islanders of Easter Island, the most remote inhabited place on Earth, and moved across it standing upright.' },
  { id: 'notredame', name: 'Notre-Dame de Paris', at: [2.350, 48.853], from: 1260, c: true, wiki: 'Notre-Dame de Paris', note: 'A Gothic cathedral with flying buttresses and great rose windows, built over a century on an island in the Seine.' },
  { id: 'djinguereber', name: 'Djinguereber Mosque', at: [-3.009, 16.771], from: 1327, wiki: 'Djinguereber Mosque', note: 'A mud-brick mosque in Timbuktu built for Mansa Musa on his return from Mecca, said to be designed by the Andalusi poet al-Sahili.' },
  { id: 'alhambra', name: 'Alhambra', at: [-3.588, 37.176], from: 1354, c: true, wiki: 'Alhambra', note: 'The palace-fortress of the Nasrid sultans of Granada, the last Muslim kingdom in Spain, with courts of fountains and carved stucco.' },
  { id: 'forbidden', name: 'Forbidden City', at: [116.397, 39.917], from: 1420, wiki: 'Forbidden City', note: 'The palace of the Ming and Qing emperors in Beijing, nearly a thousand buildings behind a moat and walls, closed to all but the court for five centuries.' },
  { id: 'porcelain', name: 'Porcelain Tower of Nanjing', at: [118.778, 32.009], from: 1431, to: 1856, wiki: 'Porcelain Tower of Nanjing', note: 'A pagoda nearly 80 m high faced with white glazed bricks, built by the Yongle Emperor. European travellers counted it among the wonders of the world; the Taiping destroyed it.' },
  { id: 'machupicchu', name: 'Machu Picchu', at: [-72.545, -13.163], from: 1450, c: true, wiki: 'Machu Picchu', note: 'An estate of the Inca emperor Pachacuti on a ridge above the Urubamba, of fitted stone without mortar. The Spanish never found it.' },
  { id: 'templomayor', name: 'Templo Mayor', at: [-99.131, 19.435], from: 1487, to: 1521, wiki: 'Templo Mayor', note: 'The twin-temple pyramid of Huitzilopochtli and Tlaloc at the heart of Tenochtitlan, rebuilt seven times. The Spanish pulled it down after the conquest.' },
  { id: 'sistine', name: 'Sistine Chapel ceiling', at: [12.454, 41.903], from: 1512, wiki: 'Sistine Chapel ceiling', note: 'Michelangelo spent four years painting the Creation and the prophets on the vault of the pope’s chapel, a high point of the Renaissance.' },
  { id: 'suleymaniye', name: 'Süleymaniye Mosque', at: [28.964, 41.016], from: 1557, wiki: 'Süleymaniye Mosque', note: 'The architect Sinan’s mosque for Suleiman the Magnificent on a hill above the Golden Horn, with schools, a hospital and a soup kitchen around it.' },
  { id: 'stbasil', name: 'St Basil’s Cathedral', at: [37.623, 55.753], from: 1561, wiki: "Saint Basil's Cathedral", note: 'Ivan the Terrible’s church on Red Square for the conquest of Kazan, a cluster of brightly painted onion domes.' },
  { id: 'isfahan', name: 'Naqsh-e Jahan Square', at: [51.678, 32.657], from: 1629, c: true, wiki: 'Naqsh-e Jahan Square', note: 'Shah Abbas’ great square in Isfahan with the Shah Mosque, the palace and the bazaar around it. “Isfahan is half the world,” went the saying.' },
  { id: 'himeji', name: 'Himeji Castle', at: [134.694, 34.839], from: 1609, wiki: 'Himeji Castle', note: 'A white castle of plastered wood on stone walls, completed just after Sekigahara, the finest survivor of the castles of the warring lords.' },
  { id: 'tajmahal', name: 'Taj Mahal', at: [78.042, 27.175], from: 1653, wiki: 'Taj Mahal', note: 'The white marble tomb Shah Jahan built for his wife Mumtaz Mahal at Agra, inlaid with stones from across Asia; some 20,000 workers took about twenty years.' },
  { id: 'potala', name: 'Potala Palace', at: [91.117, 29.658], from: 1648, wiki: 'Potala Palace', note: 'The palace of the Dalai Lamas on a hill above Lhasa, begun by the fifth Dalai Lama when he became ruler of Tibet.' },
  { id: 'versailles', name: 'Palace of Versailles', at: [2.120, 48.805], from: 1682, wiki: 'Palace of Versailles', note: 'Louis XIV’s palace, where he moved his court and government to keep the nobles close. Kings across Europe copied it.' },
  { id: 'bigben', name: 'Big Ben', at: [-0.1246, 51.5007], from: 1859, wiki: 'Big Ben', note: 'The clock tower of the rebuilt Houses of Parliament in London, capital of the largest empire in history.' },
  { id: 'liberty', name: 'Statue of Liberty', at: [-74.0445, 40.6892], from: 1886, wiki: 'Statue of Liberty', note: 'A gift from France to the United States, a copper statue on an iron frame by Gustave Eiffel, greeting millions of immigrants arriving in New York harbour.' },
  { id: 'eiffel', name: 'Eiffel Tower', at: [2.2945, 48.8584], from: 1889, wiki: 'Eiffel Tower', note: 'An iron tower 300 m high, built for the Paris world’s fair of 1889 and the tallest structure in the world for forty years.' },
];

// People of great and lasting influence, shown on the map from about age 20 to their death at the place of their
// main work. kind: ruler, faith, thinker, science or arts. c: approximate dates.
const PEOPLE = [
  { id: 'imhotep', name: 'Imhotep', kind: 'science', at: [31.216, 29.871], born: -2690, died: -2610, c: true, wiki: 'Imhotep', note: 'Chancellor of the pharaoh Djoser and architect of the Step Pyramid at Saqqara, the first great stone building. Later Egyptians worshipped him as a god of medicine.' },
  { id: 'sargon', name: 'Sargon of Akkad', kind: 'ruler', at: [44.0, 33.1], born: -2360, died: -2279, c: true, wiki: 'Sargon of Akkad', note: 'A cupbearer who made himself king and conquered the cities of Sumer and beyond, creating what is often called the first empire.' },
  { id: 'hammurabi', name: 'Hammurabi', kind: 'ruler', at: [44.42, 32.54], born: -1810, died: -1750, c: true, wiki: 'Hammurabi', note: 'King of Babylon who united Mesopotamia and had 282 laws carved on a stone stele, one of the oldest surviving law codes.' },
  { id: 'ramesses', name: 'Ramesses II', kind: 'ruler', at: [32.65, 25.70], born: -1303, died: -1213, wiki: 'Ramesses II', note: 'Pharaoh for 66 years, who fought the Hittites at Kadesh and then made the first known peace treaty with them, and built more monuments than any other.' },
  { id: 'buddha', name: 'The Buddha', kind: 'faith', at: [83.03, 25.38], born: -563, died: -483, c: true, wiki: 'The Buddha', note: 'Siddhartha Gautama, a prince who left home to seek an end to suffering and taught the Middle Way across the Ganges plain. His dates are uncertain; many scholars put them a century later.' },
  { id: 'confucius', name: 'Confucius', kind: 'thinker', at: [116.99, 35.60], born: -551, died: -479, wiki: 'Confucius', note: 'A teacher of Lu whose sayings on duty, ritual and good government, collected by his students, shaped Chinese and East Asian society for two thousand years.' },
  { id: 'cyrus', name: 'Cyrus the Great', kind: 'ruler', at: [53.17, 30.19], born: -600, died: -530, c: true, wiki: 'Cyrus the Great', note: 'Founder of the Persian Empire, who took Babylon in 539 BC and let the exiled Jews return home. Greeks and Jews alike remembered him as a model king.' },
  { id: 'plato', name: 'Plato', kind: 'thinker', at: [23.708, 37.992], born: -428, died: -348, c: true, wiki: 'Plato', note: 'Student of Socrates and founder of the Academy in Athens, whose dialogues on justice, knowledge and the ideal state began Western philosophy.' },
  { id: 'aristotle', name: 'Aristotle', kind: 'thinker', at: [23.75, 37.98], born: -384, died: -322, wiki: 'Aristotle', note: 'Plato’s student and Alexander’s tutor, who wrote on logic, biology, physics, ethics and politics. Medieval Muslim and Christian scholars called him simply “the Philosopher”.' },
  { id: 'alexander', name: 'Alexander the Great', kind: 'ruler', at: [22.52, 40.76], born: -356, died: -323, wiki: 'Alexander the Great', note: 'King of Macedon who conquered the Persian Empire from Egypt to the Indus in eleven years and spread Greek cities and culture across the east.' },
  { id: 'ashoka', name: 'Ashoka', kind: 'ruler', at: [85.14, 25.61], born: -304, died: -232, wiki: 'Ashoka', note: 'Mauryan emperor who, horrified by his conquest of Kalinga, turned to Buddhism, had edicts of tolerance carved on rocks and pillars, and sent missions abroad.' },
  { id: 'archimedes', name: 'Archimedes', kind: 'science', at: [15.29, 37.08], born: -287, died: -212, wiki: 'Archimedes', note: 'Mathematician and engineer of Syracuse who worked out the principle of buoyancy and the lever and approached the calculus. A Roman soldier killed him when the city fell.' },
  { id: 'qinshihuang', name: 'Qin Shi Huang', kind: 'ruler', at: [108.71, 34.33], born: -259, died: -210, wiki: 'Qin Shi Huang', note: 'The king of Qin who conquered the other warring states in 221 BC and called himself First Emperor, standardising script, coins, weights and axle widths.' },
  { id: 'simaqian', name: 'Sima Qian', kind: 'thinker', at: [108.94, 34.26], born: -145, died: -86, c: true, wiki: 'Sima Qian', note: 'Grand historian of the Han, whose Records of the Grand Historian set the pattern for Chinese history writing; it includes the first Chinese account of Central Asia.' },
  { id: 'caesar', name: 'Julius Caesar', kind: 'ruler', at: [12.48, 41.89], born: -100, died: -44, wiki: 'Julius Caesar', note: 'Conqueror of Gaul who crossed the Rubicon, won Rome’s civil war and made himself dictator, and was murdered in the Senate. His name became a title for emperors.' },
  { id: 'augustus', name: 'Augustus', kind: 'ruler', at: [12.49, 41.89], born: -63, died: 14, wiki: 'Augustus', note: 'Caesar’s heir and the first Roman emperor, who ended a century of civil war and ruled for 41 years behind the forms of the Republic.' },
  { id: 'jesus', name: 'Jesus', kind: 'faith', at: [35.5, 32.8], born: -4, died: 30, c: true, wiki: 'Jesus', note: 'A Jewish preacher from Galilee, crucified by the Romans in Jerusalem. His followers proclaimed him the Messiah and carried his teaching across the empire.' },
  { id: 'cailun', name: 'Cai Lun', kind: 'science', at: [112.45, 34.62], born: 50, died: 121, c: true, wiki: 'Cai Lun', note: 'A court official of the Han who in 105 presented the emperor with an improved paper made from bark, hemp and rags, which spread across the world.' },
  { id: 'constantine', name: 'Constantine the Great', kind: 'ruler', at: [28.98, 41.01], born: 272, died: 337, wiki: 'Constantine the Great', note: 'The first Christian Roman emperor, who ended the persecution of Christians and founded Constantinople as a new capital.' },
  { id: 'aryabhata', name: 'Aryabhata', kind: 'science', at: [85.14, 25.62], born: 476, died: 550, c: true, wiki: 'Aryabhata', note: 'An astronomer of Kusumapura near Pataliputra who calculated pi to four decimal places and taught that the earth turns on its axis.' },
  { id: 'justinian', name: 'Justinian I', kind: 'ruler', at: [28.97, 41.01], born: 482, died: 565, wiki: 'Justinian I', note: 'East Roman emperor who reconquered Italy and North Africa, built the Hagia Sophia and had Roman law collected into the code that underlies much of European law.' },
  { id: 'muhammad', name: 'Muhammad', kind: 'faith', at: [39.61, 24.47], born: 570, died: 632, wiki: 'Muhammad', note: 'The Prophet of Islam, a merchant of Mecca who preached the revelations of the Quran, moved to Medina in 622 and united Arabia before his death.' },
  { id: 'wuzetian', name: 'Wu Zetian', kind: 'ruler', at: [112.45, 34.62], born: 624, died: 705, wiki: 'Wu Zetian', note: 'The only woman to rule China as emperor in her own name, governing from Luoyang, promoting officials by examination and sponsoring Buddhism.' },
  { id: 'libai', name: 'Li Bai', kind: 'arts', at: [108.94, 34.27], born: 701, died: 762, wiki: 'Li Bai', note: 'The great poet of the Tang, of wine, the moon and wandering; born in Central Asia, he spent years at the court in Chang’an.' },
  { id: 'charlemagne', name: 'Charlemagne', kind: 'ruler', at: [6.08, 50.78], born: 748, died: 814, wiki: 'Charlemagne', note: 'King of the Franks who united most of western Europe and was crowned emperor by the pope in 800, reviving learning at his court in Aachen.' },
  { id: 'khwarizmi', name: 'al-Khwarizmi', kind: 'science', at: [44.37, 33.32], born: 780, died: 850, c: true, wiki: 'Al-Khwarizmi', note: 'A scholar of the House of Wisdom whose book on equations gave us the word algebra, and whose work on Indian numerals carried them west; algorithm comes from his name.' },
  { id: 'murasaki', name: 'Murasaki Shikibu', kind: 'arts', at: [135.76, 35.01], born: 973, died: 1014, c: true, wiki: 'Murasaki Shikibu', note: 'A lady of the Heian court in Kyoto who wrote The Tale of Genji, often called the first novel.' },
  { id: 'avicenna', name: 'Avicenna (Ibn Sina)', kind: 'science', at: [48.51, 34.80], born: 980, died: 1037, wiki: 'Avicenna', note: 'A Persian physician and philosopher whose Canon of Medicine was taught in the universities of Europe and the Islamic world for 600 years.' },
  { id: 'saladin', name: 'Saladin', kind: 'ruler', at: [36.30, 33.51], born: 1137, died: 1193, wiki: 'Saladin', note: 'Sultan of Egypt and Syria who retook Jerusalem from the Crusaders in 1187, respected even by his enemies for his chivalry.' },
  { id: 'genghis', name: 'Genghis Khan', kind: 'ruler', at: [108.9, 48.3], born: 1162, died: 1227, wiki: 'Genghis Khan', note: 'Temüjin united the Mongol tribes in 1206 and led them in conquests from northern China to Iran, beginning the largest land empire in history.' },
  { id: 'rumi', name: 'Rumi', kind: 'faith', at: [32.48, 37.87], born: 1207, died: 1273, wiki: 'Rumi', note: 'A Persian poet and Sufi mystic in Konya whose verses of divine love are read across the world; his followers became the whirling dervishes.' },
  { id: 'kublai', name: 'Kublai Khan', kind: 'ruler', at: [116.39, 39.91], born: 1215, died: 1294, wiki: 'Kublai Khan', note: 'Genghis’ grandson, who conquered the Song and ruled all China as the first Yuan emperor from his new capital, Khanbaliq. Marco Polo served at his court.' },
  { id: 'dante', name: 'Dante Alighieri', kind: 'arts', at: [11.256, 43.773], born: 1265, died: 1321, wiki: 'Dante Alighieri', note: 'A Florentine poet who wrote the Divine Comedy, a journey through hell, purgatory and heaven, in Italian rather than Latin.' },
  { id: 'mansamusa', name: 'Mansa Musa', kind: 'ruler', at: [-8.4, 11.4], born: 1280, died: 1337, c: true, wiki: 'Mansa Musa', note: 'Emperor of Mali, perhaps the richest man of his age, whose pilgrimage to Mecca in 1324 put Mali on European maps.' },
  { id: 'ibnkhaldun', name: 'Ibn Khaldun', kind: 'thinker', at: [10.17, 36.80], born: 1332, died: 1406, wiki: 'Ibn Khaldun', note: 'A North African historian whose Muqaddimah explained the rise and fall of dynasties through group solidarity, a forerunner of sociology and economics.' },
  { id: 'gutenberg', name: 'Johannes Gutenberg', kind: 'science', at: [8.27, 50.00], born: 1400, died: 1468, c: true, wiki: 'Johannes Gutenberg', note: 'A goldsmith of Mainz who built a printing press with movable metal type around 1450, making books cheap and spreading ideas across Europe.' },
  { id: 'mehmed', name: 'Mehmed II', kind: 'ruler', at: [28.95, 41.02], born: 1432, died: 1481, wiki: 'Mehmed II', note: 'The Ottoman sultan who took Constantinople in 1453 at the age of 21 and made it his capital, ending the Roman Empire in the east.' },
  { id: 'leonardo', name: 'Leonardo da Vinci', kind: 'arts', at: [9.19, 45.46], born: 1452, died: 1519, wiki: 'Leonardo da Vinci', note: 'Painter of the Last Supper and the Mona Lisa, whose notebooks fill with anatomy, flying machines and engineering.' },
  { id: 'nanak', name: 'Guru Nanak', kind: 'faith', at: [75.0, 31.9], born: 1469, died: 1539, wiki: 'Guru Nanak', note: 'Founder of Sikhism in the Punjab, who taught devotion to one God and the equality of all people.' },
  { id: 'copernicus', name: 'Nicolaus Copernicus', kind: 'science', at: [19.68, 54.36], born: 1473, died: 1543, wiki: 'Nicolaus Copernicus', note: 'A canon of Frombork in Poland whose book, published as he died, put the sun rather than the earth at the centre of the universe.' },
  { id: 'luther', name: 'Martin Luther', kind: 'faith', at: [12.65, 51.87], born: 1483, died: 1546, wiki: 'Martin Luther', note: 'A monk of Wittenberg whose Ninety-five Theses of 1517 against the sale of indulgences began the Protestant Reformation; printing spread his writings fast.' },
  { id: 'suleiman', name: 'Suleiman the Magnificent', kind: 'ruler', at: [28.98, 41.01], born: 1494, died: 1566, wiki: 'Suleiman the Magnificent', note: 'Ottoman sultan for 46 years, who took Belgrade and Hungary and besieged Vienna; his people called him the Lawgiver.' },
  { id: 'akbar', name: 'Akbar', kind: 'ruler', at: [78.01, 27.18], born: 1542, died: 1605, wiki: 'Akbar', note: 'Mughal emperor who conquered most of north India, ended the tax on non-Muslims and hosted debates between faiths at his court.' },
  { id: 'elizabeth', name: 'Elizabeth I', kind: 'ruler', at: [-0.13, 51.50], born: 1533, died: 1603, wiki: 'Elizabeth I', note: 'Queen of England for 45 years, who saw off the Spanish Armada and chartered the East India Company.' },
  { id: 'galileo', name: 'Galileo Galilei', kind: 'science', at: [11.25, 43.77], born: 1564, died: 1642, wiki: 'Galileo Galilei', note: 'He turned the new telescope to the sky, saw the moons of Jupiter and defended the sun-centred universe, for which the Inquisition confined him to his house.' },
  { id: 'shakespeare', name: 'William Shakespeare', kind: 'arts', at: [-0.10, 51.51], born: 1564, died: 1616, wiki: 'William Shakespeare', note: 'Playwright and poet of London’s Globe theatre, author of Hamlet, Macbeth and some 37 other plays.' },
  { id: 'newton', name: 'Isaac Newton', kind: 'science', at: [0.12, 52.21], born: 1643, died: 1727, wiki: 'Isaac Newton', note: 'A Cambridge scholar whose laws of motion and universal gravitation, published in 1687, explained the movements of the planets and the fall of an apple alike.' },
  { id: 'kangxi', name: 'Kangxi Emperor', kind: 'ruler', at: [116.40, 39.92], born: 1654, died: 1722, wiki: 'Kangxi Emperor', note: 'The longest-reigning Chinese emperor, who completed the Qing conquest, took Taiwan, made the first border treaty with Russia and kept Jesuit astronomers at court.' },
  { id: 'peter', name: 'Peter the Great', kind: 'ruler', at: [30.31, 59.94], born: 1672, died: 1725, wiki: 'Peter the Great', note: 'Tsar who toured the shipyards of Holland and England, then remade Russia on European lines and built St Petersburg as its new capital.' },
  { id: 'adamsmith', name: 'Adam Smith', kind: 'thinker', at: [-3.19, 55.95], born: 1723, died: 1790, wiki: 'Adam Smith', note: 'A Scottish philosopher whose Wealth of Nations of 1776 explained how markets and the division of labour make nations rich.' },
  { id: 'washington', name: 'George Washington', kind: 'ruler', at: [-77.09, 38.71], born: 1732, died: 1799, wiki: 'George Washington', note: 'Commander of the American army in the war of independence and first president of the United States, who gave up power after two terms.' },
  { id: 'watt', name: 'James Watt', kind: 'science', at: [-1.90, 52.48], born: 1736, died: 1819, wiki: 'James Watt', note: 'A Scottish instrument maker whose improved steam engine, built with Matthew Boulton in Birmingham, powered the mills and mines of the Industrial Revolution.' },
  { id: 'napoleon', name: 'Napoleon Bonaparte', kind: 'ruler', at: [2.33, 48.86], born: 1769, died: 1821, wiki: 'Napoleon', note: 'A Corsican general who made himself emperor of the French, conquered most of Europe and left it his law code, until his defeat at Waterloo.' },
  { id: 'beethoven', name: 'Ludwig van Beethoven', kind: 'arts', at: [16.37, 48.21], born: 1770, died: 1827, wiki: 'Ludwig van Beethoven', note: 'A composer in Vienna who kept writing as he went deaf; his symphonies bridged the classical and romantic ages.' },
  { id: 'bolivar', name: 'Simón Bolívar', kind: 'ruler', at: [-66.90, 10.49], born: 1783, died: 1830, wiki: 'Simón Bolívar', note: 'The Liberator, who led the wars that freed Venezuela, Colombia, Ecuador, Peru and Bolivia from Spain.' },
  { id: 'shaka', name: 'Shaka', kind: 'ruler', at: [31.5, -28.4], born: 1787, died: 1828, c: true, wiki: 'Shaka', note: 'King of the Zulu who reorganised their army and forged a powerful kingdom in southern Africa through war.' },
  { id: 'lincoln', name: 'Abraham Lincoln', kind: 'ruler', at: [-77.04, 38.90], born: 1809, died: 1865, wiki: 'Abraham Lincoln', note: 'President of the United States through the Civil War, who ended slavery; he was murdered days after the war ended.' },
  { id: 'darwin', name: 'Charles Darwin', kind: 'science', at: [0.05, 51.33], born: 1809, died: 1882, wiki: 'Charles Darwin', note: 'A naturalist whose voyage on the Beagle led to On the Origin of Species of 1859, explaining how life evolves by natural selection.' },
  { id: 'bismarck', name: 'Otto von Bismarck', kind: 'ruler', at: [13.40, 52.52], born: 1815, died: 1898, wiki: 'Otto von Bismarck', note: 'Prussian chancellor who united Germany through three short wars and then kept the peace of Europe; he hosted the Berlin conference that divided Africa.' },
  { id: 'marx', name: 'Karl Marx', kind: 'thinker', at: [-0.13, 51.52], born: 1818, died: 1883, wiki: 'Karl Marx', note: 'A German exile in London whose Communist Manifesto and Capital, on class struggle and the workings of capitalism, inspired revolutions in the century after.' },
  { id: 'victoria', name: 'Queen Victoria', kind: 'ruler', at: [-0.14, 51.50], born: 1819, died: 1901, wiki: 'Queen Victoria', note: 'Queen for 63 years and from 1876 Empress of India, she gave her name to the age when Britain’s industry and empire were at their height.' },
  { id: 'edison', name: 'Thomas Edison', kind: 'science', at: [-74.34, 40.56], born: 1847, died: 1931, wiki: 'Thomas Edison', note: 'An American inventor whose laboratory at Menlo Park produced the phonograph, a practical light bulb and electric power stations.' },
  { id: 'meiji', name: 'Emperor Meiji', kind: 'ruler', at: [139.75, 35.68], born: 1852, died: 1912, wiki: 'Emperor Meiji', note: 'Restored to power in 1868, his reign saw Japan abolish the samurai class, build railways, factories and a modern army, and defeat China in 1895.' },
  { id: 'curie', name: 'Marie Curie', kind: 'science', at: [2.34, 48.85], born: 1867, died: 1934, wiki: 'Marie Curie', note: 'A Polish-born physicist in Paris who discovered polonium and radium with her husband Pierre in 1898, and the first person to win two Nobel prizes.' },
];
